  "./js/core/store.js",
  "./js/core/util.js",
  "./js/lessons.js",
  "./js/main.js",
  "./js/modes/calibrate.js",
  "./js/modes/chords.js",
  "./js/modes/common.js",
  "./js/modes/findnote.js",
  "./js/modes/flash.js",
  "./js/modes/freeplay.js",
  "./js/modes/higherlower.js",
